package com.example.riskplatform.security;
import io.jsonwebtoken.*;import io.jsonwebtoken.security.Keys;import org.springframework.beans.factory.annotation.Value;import org.springframework.stereotype.Component;import javax.crypto.SecretKey;import java.nio.charset.StandardCharsets;import java.util.Date;
@Component public class JwtUtil{private final SecretKey key;private final long exp;public JwtUtil(@Value("${app.jwt.secret}")String s,@Value("${app.jwt.expiration-seconds:86400}")long e){key=Keys.hmacShaKeyFor(s.getBytes(StandardCharsets.UTF_8));exp=e*1000;}public String generate(String u){Date n=new Date();return Jwts.builder().subject(u).issuedAt(n).expiration(new Date(n.getTime()+exp)).signWith(key).compact();}public String parseUsername(String t){return Jwts.parser().verifyWith(key).build().parseSignedClaims(t).getPayload().getSubject();}}
